// Domestic client yysls.exe; the international client (Steam and the global
// launcher, S39) is wwm.exe in the same two entry folders.
inline bool International(const wchar_t* path) {
    const auto* leaf=std::wcsrchr(path,L'\\');return leaf&&!_wcsicmp(leaf+1,L"wwm.exe");
}
inline bool Layout(const wchar_t* path) {
    const auto* leaf=std::wcsrchr(path,L'\\');if(!leaf||(_wcsicmp(leaf+1,L"yysls.exe")&&_wcsicmp(leaf+1,L"wwm.exe")))return false;
    const wchar_t* suffixes[]={L"\\Engine\\Binaries\\Win64r\\yysls.exe",L"\\Engine\\Binaries\\Win64rh\\yysls.exe",
                               L"\\Engine\\Binaries\\Win64r\\wwm.exe",L"\\Engine\\Binaries\\Win64rh\\wwm.exe"};
    const size_t len=std::wcslen(path);
    for(auto suffix:suffixes){const size_t n=std::wcslen(suffix);if(len>n&&!_wcsicmp(path+len-n,suffix))return true;}
    return false;
}
inline bool Icon(const void* bytes,size_t length){return bytes&&length==sizeof(icon)&&!std::memcmp(bytes,icon,length);}
inline bool HostSupported() {
    wchar_t path[32768]{};const DWORD length=GetModuleFileNameW(nullptr,path,32768);
    if(!length||length>=32768||!Layout(path))return false;
    // The pinned icon is the domestic client's; no international client has been
    // read yet, so wwm.exe is recognised by its layout alone.
    if(International(path))return true;
    const HMODULE host=GetModuleHandleW(nullptr);const HRSRC resource=FindResourceW(host,MAKEINTRESOURCEW(1),MAKEINTRESOURCEW(3));
    if(!resource)return false;const DWORD bytes=SizeofResource(host,resource);if(bytes!=sizeof(icon))return false;
    const HGLOBAL loaded=LoadResource(host,resource);return loaded&&Icon(LockResource(loaded),bytes);
}
